#include <iostream>
#include <vector>
#include <string>
#include <cctype>
#include <algorithm>

int main() {
    std::vector<std::string> segments;
    std::vector<std::string> parenthesesContents;
    int length;
    std::cin >> length;
    std::string str;
    std::cin >> str;
    str += "^";
    int totalLen = length + 1;
    char buffer[256];
    for (int i = 0; i < totalLen; i++) {
        buffer[i] = str[i];
    }
    int inParentheses = 0;
    std::string tempStr = "";
    for (int i = 0; i < totalLen; i++) {
        if (buffer[i] == '(') {
            inParentheses = 1;
            buffer[i] = '^';
            continue;
        } else if (buffer[i] == ')') {
            inParentheses = 0;
            parenthesesContents.push_back(tempStr);
            buffer[i] = '^';
            tempStr = "";
        }
        if (inParentheses == 1) {
            tempStr += buffer[i];
            buffer[i] = '^';
        }
    }
    tempStr = "";
    for (int i = 0; i < totalLen; i++) {
        if (buffer[i] == '^') {
            if (tempStr.empty()) continue;
            segments.push_back(tempStr);
            tempStr = "";
        } else {
            tempStr += buffer[i];
        }
    }
    int maxLetters = 0;
    int totalWordsCount = 0;
    for (const auto& segment : segments) {
        std::string s = segment + "_";
        int letterCount = 0;
        for (size_t j = 0; j < s.length(); j++) {
            if (std::isalpha(s[j])) {
                letterCount++;
            } else if (s[j] == '_') {
                maxLetters = std::max(maxLetters, letterCount);
                letterCount = 0;
            }
        }
    }
    int wordCount = 0;
    for (const auto& content : parenthesesContents) {
        std::string s = content + "_";
        std::string wordBuilder = "";
        for (size_t j = 0; j < s.length(); j++) {
            if (std::isalpha(s[j])) {
                wordBuilder += s[j];
            } else if (s[j] == '_' && !wordBuilder.empty()) {
                wordBuilder = "";
                wordCount++;
            }
        }
    }
    std::cout << maxLetters << " " << wordCount << std::endl;
    return 0;
}
